validator:
function validate(input) {
  const [{ Employees = [] }] = input;
  const ids = new Set();
  for (const [id, name, salary] of Employees) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (ids.has(id)) return `employee_id ${id} appears twice.`;
    ids.add(id);
    if (name === null) return 'Every employee needs a name.';
    if (salary === null) return 'Every employee needs a salary.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const names = ['Meir', 'Michael', 'Addilyn', 'Juan', 'Kannon', 'Ana', 'Ravi', 'Sofia', 'Lee', 'Kim'];
  const count = size === 'small' ? pick(9) : 1800;
  const salaries = size === 'small'
    ? [3000, 4500, 6100, 7400, 9000].slice(0, 2 + pick(4))
    : Array.from({ length: 1100 }, (_, i) => 1000 + 7 * i);
  // Distinct ids drawn from a wider range and inserted in random order.
  const ids = new Set();
  while (ids.size < count) ids.add(1 + pick(count * 3 + 5));
  const Employees = [...ids].map((id) => [id, names[pick(names.length)], salaries[pick(salaries.length)]]);
  return [{ Employees }];
}
